//! A display controller's market name, the way its maker sells it
//! ("NVIDIA GeForce RTX 5080", "AMD Radeon RX 7900 XTX", "Intel Arc A770"),
//! for the boot screen and log. The table is generated by `cargo xtask gpu
//! names` from pinned sources (`xtask/src/gpu/names.rs`): the PCI ID
//! database, libdrm's `amdgpu.ids`, which names AMD devices by revision,
//! Mesa's Intel device tables and amdgpu's own table for the processors'
//! GPUs. A device none of them names is called by its maker alone ("NVIDIA
//! GPU"): its PCI IDs tell a user nothing, and the log's `GPU SELECT` line
//! holds them.
use crate::Vendor;
use alloc::{format, string::String};

mod table;

#[cfg(test)]
mod coverage;

/// The table's entry for any revision of a device.
const ANY: u16 = 0x100;

/// Where the names come from: the `pci.ids` release and the libdrm and Mesa
/// commits.
pub const SOURCES: &str = table::SOURCES;

/// The market name of the display controller `device` of `vendor` at
/// `revision`, if the table holds one: AMD's names for that revision first,
/// then the name of the device.
pub fn market_name(vendor: Vendor, device: u16, revision: u8) -> Option<String> {
    let maker = maker(vendor)?;
    let vendor = vendor.pci_id();
    let find = |revision: u16| {
        table::ENTRIES
            .binary_search_by_key(
                &(vendor, device, revision),
                |&(vendor, device, revision, _)| (vendor, device, revision),
            )
            .ok()
    };
    let index = find(u16::from(revision)).or_else(|| find(ANY))?;
    let start = table::ENTRIES[index].3 as usize;
    let name = table::TEXT.get(start..)?.split('\n').next()?;
    Some(format!("{maker} {name}"))
}

/// [`market_name`], else the maker alone: "NVIDIA GPU", or "display
/// adapter" for a maker without a GPU stack. PCI IDs tell a user nothing:
/// the log's `GPU SELECT` line holds them.
pub fn name(vendor: Vendor, device: u16, revision: u8) -> String {
    market_name(vendor, device, revision).unwrap_or_else(|| match maker(vendor) {
        Some(maker) => format!("{maker} GPU"),
        None => String::from("display adapter"),
    })
}

/// How the maker of `vendor`'s display controllers sells them.
fn maker(vendor: Vendor) -> Option<&'static str> {
    match vendor {
        Vendor::Nvidia => Some("NVIDIA"),
        Vendor::Amd => Some("AMD"),
        Vendor::Intel => Some("Intel"),
        Vendor::Other(_) => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_devices_have_their_market_names() {
        let named = |vendor, device, revision| market_name(vendor, device, revision);
        // NVIDIA by device: an RTX 5080, a laptop's RTX 4060.
        assert_eq!(
            named(Vendor::Nvidia, 0x2c02, 0xa1).as_deref(),
            Some("NVIDIA GeForce RTX 5080")
        );
        assert_eq!(
            named(Vendor::Nvidia, 0x2b85, 0xa1).as_deref(),
            Some("NVIDIA GeForce RTX 5090")
        );
        // AMD by device and revision: Navi 31's three cards.
        assert_eq!(
            named(Vendor::Amd, 0x744c, 0xc8).as_deref(),
            Some("AMD Radeon RX 7900 XTX")
        );
        assert_eq!(
            named(Vendor::Amd, 0x744c, 0xcc).as_deref(),
            Some("AMD Radeon RX 7900 XT")
        );
        // Granite Ridge's iGPU (Ryzen 9000), which amdgpu.ids does not
        // list: the database's name of the device, whatever the revision.
        assert_eq!(
            named(Vendor::Amd, 0x13c0, 0xcb).as_deref(),
            Some("AMD Radeon Graphics")
        );
        // Intel: an Arc card, a desktop and a laptop integrated GPU.
        assert_eq!(
            named(Vendor::Intel, 0x56a0, 0x08).as_deref(),
            Some("Intel Arc A770")
        );
        assert_eq!(
            named(Vendor::Intel, 0xa780, 0x04).as_deref(),
            Some("Intel UHD Graphics 770")
        );
        assert_eq!(
            named(Vendor::Intel, 0x9a49, 0x01).as_deref(),
            Some("Intel Iris Xe Graphics")
        );
        assert!(SOURCES.starts_with("pci.ids "));
    }

    #[test]
    fn an_unknown_device_is_named_by_its_maker_alone() {
        assert_eq!(market_name(Vendor::Nvidia, 0xfffe, 0), None);
        assert_eq!(name(Vendor::Nvidia, 0xfffe, 0), "NVIDIA GPU");
        assert_eq!(name(Vendor::Amd, 0xfffe, 0xc1), "AMD GPU");
        assert_eq!(name(Vendor::Intel, 0xfffe, 0), "Intel GPU");
        // ASPEED's BMC display: no maker's name.
        assert_eq!(market_name(Vendor::Other(0x1a03), 0x2000, 0x52), None);
        assert_eq!(name(Vendor::Other(0x1a03), 0x2000, 0x52), "display adapter");
        // A non-display function's ID names nothing: NVIDIA's HD audio.
        assert_eq!(market_name(Vendor::Nvidia, 0x22e8, 0xa1), None);
        assert_eq!(
            name(Vendor::Nvidia, 0x2c02, 0xa1),
            "NVIDIA GeForce RTX 5080"
        );
    }

    #[test]
    fn the_table_is_sorted_and_every_name_is_whole() {
        assert!(
            table::ENTRIES
                .windows(2)
                .all(|pair| (pair[0].0, pair[0].1, pair[0].2) < (pair[1].0, pair[1].1, pair[1].2))
        );
        for &(vendor, _, revision, start) in &table::ENTRIES {
            assert!([0x10de, 0x1002, 0x8086].contains(&vendor));
            assert!(revision <= ANY);
            let start = start as usize;
            assert!(start == 0 || table::TEXT.as_bytes()[start - 1] == b'\n');
            let name = table::TEXT[start..].split('\n').next().unwrap();
            assert!(!name.is_empty() && name.trim() == name, "{name:?}");
        }
    }
}
